// Molecular Basis of Inheritance - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'

export const MOLECULAR_BASIS_INHERITANCE = [

  // ============ SEARCH FOR GENETIC MATERIAL ============
  { id: 'mbi-1', type: 'mcq', question: 'Frederick Griffith, in 1928, conducted transformation experiments using which bacterium?', options: ['Escherichia coli', 'Streptococcus pneumoniae', 'Bacillus subtilis', 'Salmonella typhimurium'], correctIndex: 1, explanation: 'Griffith worked with Streptococcus pneumoniae, studying virulent (S-strain) and non-virulent (R-strain) forms of the bacterium in mice.', difficulty: 'medium' },
  { id: 'mbi-2', type: 'mcq', question: 'In Griffith\'s experiment, mice injected with a mixture of heat-killed S-strain bacteria and live R-strain (non-virulent) bacteria:', options: ['Remained completely healthy, with no bacteria recovered', 'Died, and living S-strain bacteria were recovered from their blood', 'Died, but only R-strain bacteria were recovered', 'Showed no change in bacterial strains present'], correctIndex: 1, explanation: 'Mice injected with heat-killed S-strain plus live R-strain died, and living S-strain bacteria were recovered, indicating the R-strain bacteria had been "transformed".', difficulty: 'medium' },
  { id: 'mbi-3', type: 'mcq', question: 'Griffith concluded that the R-strain bacteria had been "transformed" by some substance from the heat-killed S-strain bacteria; this substance was named the:', options: ['Transforming principle', 'Genetic code', 'Recombinant factor', 'Virulence factor only'], correctIndex: 0, explanation: 'Griffith termed the unidentified substance responsible for changing R-strain bacteria into virulent S-strain bacteria as the "transforming principle".', difficulty: 'medium' },
  { id: 'mbi-4', type: 'mcq', question: 'The biochemical identity of the "transforming principle" discovered by Griffith was later determined by which scientists?', options: ['Watson and Crick', 'Avery, MacLeod and McCarty', 'Hershey and Chase', 'Meselson and Stahl'], correctIndex: 1, explanation: 'Avery, MacLeod and McCarty (1933–44) worked to biochemically identify the transforming substance discovered by Griffith.', difficulty: 'medium' },
  { id: 'mbi-5', type: 'mcq', question: 'Avery, MacLeod and McCarty concluded that DNA was the transforming principle by showing that:', options: ['Only DNA digestion (with DNase) stopped the transformation, while treatment with protease or RNase did not', 'Protein digestion alone stopped transformation', 'RNA digestion alone stopped transformation', 'None of the enzymatic treatments had any effect'], correctIndex: 0, explanation: 'They found that only enzymes degrading DNA (DNase) could stop transformation, while proteases and RNases had no effect, indicating DNA was the genetic material.', difficulty: 'medium' },
  { id: 'mbi-6', type: 'mcq', question: 'The Hershey-Chase experiment (1952), which provided further conclusive evidence that DNA is the genetic material, was conducted using:', options: ['Streptococcus pneumoniae', 'Bacteriophages that infect Escherichia coli', 'Garden pea plants', 'Human blood cells'], correctIndex: 1, explanation: 'Hershey and Chase used bacteriophages (viruses that infect bacteria) to demonstrate that DNA, not protein, is the genetic material transmitted to progeny phages.', difficulty: 'medium' },
  { id: 'mbi-7', type: 'mcq', question: 'In the Hershey-Chase experiment, bacteriophage DNA and protein coats were labelled with different radioactive isotopes; which isotopes were used respectively for DNA and protein?', options: ['Phosphorus-32 (DNA) and sulphur-35 (protein)', 'Carbon-14 (DNA) and nitrogen-15 (protein)', 'Sulphur-35 (DNA) and phosphorus-32 (protein)', 'Hydrogen-3 (DNA) and oxygen-18 (protein)'], correctIndex: 0, explanation: 'DNA was labelled with radioactive phosphorus (32P), since DNA contains phosphorus but not sulphur, while protein coats were labelled with radioactive sulphur (35S), since proteins contain sulphur but not phosphorus.', difficulty: 'medium' },
  { id: 'mbi-8', type: 'mcq', question: 'In the Hershey-Chase experiment, after allowing phages to infect bacteria and then agitating/blending to separate phage coats from bacteria, most of the radioactivity was found in:', options: ['The bacterial cells (from phages labelled with 32P), showing DNA enters the cell', 'The supernatant/phage coats (from phages labelled with 32P)', 'Equal amounts in both phage coats and bacterial cells, regardless of isotope', 'Neither fraction showed any radioactivity at all'], correctIndex: 0, explanation: 'Radioactivity from 32P-labelled DNA was found inside the bacterial cells, showing that phage DNA entered the bacterium, while radioactivity from 35S-labelled protein remained outside in the phage coats.', difficulty: 'hard' },
  { id: 'mbi-9', type: 'mcq', question: 'The key conclusion drawn from the Hershey-Chase experiment was that:', options: ['Protein is the genetic material transmitted from parent phage to progeny', 'DNA, not protein, is the genetic material that enters the bacterium and directs the formation of progeny phages', 'Both DNA and protein equally contribute genetic information', 'Neither DNA nor protein plays any role in phage reproduction'], correctIndex: 1, explanation: 'The experiment showed that DNA, and not protein, enters the bacterial cell and is responsible for directing the synthesis of new phage particles, confirming DNA as the genetic material.', difficulty: 'medium' },
  { id: 'mbi-10', type: 'assertion', question: 'Assertion (A): The Hershey-Chase experiment provided more conclusive evidence for DNA as genetic material than Griffith\'s experiment alone.\nReason (R): The use of distinct radioactive labels for DNA and protein allowed direct tracking of which molecule entered the bacterial cell during infection, precisely identifying DNA as the material transmitted to progeny.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The precise radioactive tracking method used in the Hershey-Chase experiment correctly explains why it offered more direct and conclusive evidence compared to Griffith\'s earlier observations.', difficulty: 'hard' },
  { id: 'mbi-11', type: 'count', question: 'Consider the following statements about the search for genetic material:\n1. Griffith\'s experiment demonstrated the phenomenon of transformation in bacteria.\n2. Avery, MacLeod and McCarty identified DNA as the transforming principle.\n3. Hershey and Chase used radioactive labelling to show that protein enters bacterial cells during phage infection.\n4. The transforming principle was initially of unknown chemical identity when first described by Griffith.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — Hershey and Chase showed that DNA (not protein) enters the bacterial cell.', difficulty: 'medium' },

  // ============ WHY DNA (AND NOT RNA) — PROPERTIES OF GENETIC MATERIAL ============
  { id: 'mbi-12', type: 'mcq', question: 'A candidate molecule for genetic material must be capable of doing all of the following EXCEPT:', options: ['Replicating itself faithfully', 'Being chemically and structurally stable', 'Providing scope for slow mutation for evolution', 'Being permanently unchangeable, even over evolutionary time'], correctIndex: 3, explanation: 'While genetic material must be relatively stable, it must also allow for occasional (slow) mutation, which drives evolution — being permanently unchangeable would be an unrealistic requirement.', difficulty: 'medium' },
  { id: 'mbi-13', type: 'mcq', question: 'Compared to RNA, DNA is chemically more stable mainly because:', options: ['DNA lacks the 2\'-OH group present in RNA, which makes RNA more reactive and prone to degradation', 'DNA contains uracil, which is more stable than thymine', 'DNA is single-stranded, unlike RNA', 'DNA does not contain a sugar-phosphate backbone'], correctIndex: 0, explanation: 'The absence of a reactive 2\'-OH group in deoxyribose makes DNA more chemically stable than RNA, which has this group and is thus more prone to hydrolysis.', difficulty: 'medium' },
  { id: 'mbi-14', type: 'mcq', question: 'Since RNA is a catalytic molecule (in some cases) as well as reactive, it is considered:', options: ['More stable than DNA', 'Less stable than DNA, and thus RNA may have preceded DNA as genetic material in the early stages of evolution', 'Equally stable to DNA in every context', 'Completely incapable of storing genetic information'], correctIndex: 1, explanation: 'RNA\'s relative instability and catalytic ability support the hypothesis that it may have been the first genetic material, with DNA evolving later due to its superior stability.', difficulty: 'medium' },
  { id: 'mbi-15', type: 'mcq', question: 'The mutation rate is generally lower in DNA than in RNA mainly because:', options: ['DNA exists as a double helix, and any changes are subjected to proofreading and correction by cellular repair mechanisms', 'DNA does not use nitrogenous bases', 'RNA molecules are always longer than DNA molecules', 'DNA cannot undergo replication at all'], correctIndex: 0, explanation: 'The double-stranded structure of DNA allows for repair and proofreading mechanisms during replication, reducing the mutation rate compared to single-stranded RNA.', difficulty: 'medium' },
  { id: 'mbi-16', type: 'assertion', question: 'Assertion (A): DNA is generally considered a better genetic material than RNA.\nReason (R): DNA\'s greater chemical stability and lower mutation rate (due to available repair mechanisms) make it more suitable for long-term storage and faithful transmission of genetic information.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The properties of stability and repairability correctly explain why DNA is generally favoured as the primary genetic material over RNA in most organisms.', difficulty: 'medium' },
  { id: 'mbi-17', type: 'count', question: 'Consider the following statements comparing DNA and RNA as genetic material:\n1. DNA lacks a 2\'-OH group, making it more chemically stable than RNA.\n2. RNA is generally considered less stable and more reactive than DNA.\n3. All organisms exclusively use DNA as their genetic material, with no exceptions.\n4. The relative instability of RNA supports the hypothesis that RNA may have been an early genetic material before DNA evolved.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — some viruses use RNA as their genetic material, so DNA is not universal across all organisms.', difficulty: 'medium' },

  // ============ DNA STRUCTURE (RECAP AND EXPANSION) ============
  { id: 'mbi-18', type: 'mcq', question: 'The double helix model of DNA structure was proposed in 1953 by:', options: ['Watson and Crick', 'Avery and MacLeod', 'Griffith and Chase', 'Meselson and Stahl'], correctIndex: 0, explanation: 'James Watson and Francis Crick proposed the double helix model of DNA structure in 1953, based partly on X-ray diffraction data from Rosalind Franklin and Maurice Wilkins.', difficulty: 'easy' },
  { id: 'mbi-19', type: 'mcq', question: 'The two polynucleotide chains of the DNA double helix are oriented in which manner relative to each other?', options: ['Parallel, running in the same 5\' to 3\' direction', 'Antiparallel, running in opposite polarity', 'Randomly oriented, with no fixed pattern', 'Perpendicular to each other'], correctIndex: 1, explanation: 'The two DNA strands are antiparallel, meaning one runs 5\' to 3\' while the other runs 3\' to 5\' in the opposite direction.', difficulty: 'medium' },
  { id: 'mbi-20', type: 'mcq', question: 'The sugar-phosphate backbone of a DNA strand lies on which part of the double helix, while the nitrogenous bases project:', options: ['Backbone on the outside; bases project inward, paired with those of the opposite strand', 'Backbone on the inside; bases project outward', 'Both backbone and bases lie on the outside, with no interior structure', 'Backbone and bases alternate randomly along the helix surface'], correctIndex: 0, explanation: 'In the DNA double helix, the sugar-phosphate backbone forms the outer framework, while the nitrogenous bases are oriented inward and pair with complementary bases of the opposite strand.', difficulty: 'medium' },
  { id: 'mbi-21', type: 'mcq', question: 'One full turn of the DNA double helix, in the common B-form, spans approximately how many base pairs and what distance?', options: ['10 base pairs, spanning about 34 Angstroms', '5 base pairs, spanning about 10 Angstroms', '20 base pairs, spanning about 68 Angstroms', '3 base pairs, spanning about 3.4 Angstroms'], correctIndex: 0, explanation: 'One complete turn of the B-DNA double helix contains approximately 10 base pairs and measures about 34 Angstroms (3.4 nm) in length.', difficulty: 'medium' },
  { id: 'mbi-22', type: 'mcq', question: 'The distance between two consecutive base pairs stacked along the DNA helix is approximately:', options: ['3.4 Angstroms', '34 Angstroms', '20 Angstroms', '0.34 Angstroms'], correctIndex: 0, explanation: 'The distance between adjacent base pairs in the DNA helix is approximately 3.4 Angstroms (0.34 nm).', difficulty: 'medium' },
  { id: 'mbi-23', type: 'mcq', question: 'The base pairing rule in DNA states that adenine pairs specifically with thymine, and guanine pairs specifically with cytosine; this is referred to as:', options: ['Non-complementary pairing', 'Complementary base pairing', 'Random pairing', 'Wobble pairing exclusively'], correctIndex: 1, explanation: 'Complementary base pairing (A-T and G-C) ensures that the two strands of DNA are complementary to each other, a key feature underlying DNA replication.', difficulty: 'easy' },
  { id: 'mbi-24', type: 'mcq', question: 'Because the two strands of DNA are complementary rather than identical, if the sequence of bases on one strand is known, then:', options: ['Nothing can be predicted about the second strand', 'The sequence on the other strand can be predicted', 'Only the length of the other strand can be estimated', 'The other strand must always be composed only of purines'], correctIndex: 1, explanation: 'Since base pairing follows fixed complementary rules, knowing the sequence of one strand allows prediction of the exact sequence on the complementary strand.', difficulty: 'medium' },
  { id: 'mbi-25', type: 'assertion', question: 'Assertion (A): DNA is a relatively stable, negatively charged molecule.\nReason (R): The phosphate groups within the sugar-phosphate backbone of DNA carry a negative charge, making the overall DNA molecule negatively charged.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The presence of negatively charged phosphate groups in the backbone directly explains why DNA carries an overall negative charge, correctly matching the assertion.', difficulty: 'medium' },
  { id: 'mbi-26', type: 'count', question: 'Consider the following statements about DNA structure:\n1. The two DNA strands run antiparallel to each other.\n2. The sugar-phosphate backbone lies on the inside of the helix.\n3. One turn of the B-DNA helix contains approximately 10 base pairs.\n4. Adenine pairs with cytosine, and guanine pairs with thymine.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct. Statement 2 is wrong (the backbone lies on the outside, not inside), and statement 4 is wrong (the correct pairing is A-T and G-C, not A-C and G-T).', difficulty: 'medium' },
  { id: 'mbi-27', type: 'matching', question: 'Match Column I (DNA feature) with Column II (description):\nColumn I: A. Complementary base pairing  B. Antiparallel strands  C. Negatively charged backbone  D. B-DNA helix turn\nColumn II: i. Contains phosphate groups  ii. A pairs with T, G pairs with C  iii. Approximately 10 base pairs per turn  iv. Strands run in opposite 5\'→3\' directions', options: ['A-ii, B-iv, C-i, D-iii', 'A-i, B-ii, C-iii, D-iv', 'A-ii, B-iii, C-iv, D-i', 'A-iv, B-i, C-ii, D-iii'], correctIndex: 0, explanation: 'Complementary base pairing — A-T, G-C rule; Antiparallel strands — opposite 5\'→3\' directions; Negatively charged backbone — phosphate groups; B-DNA helix turn — ~10 base pairs.', difficulty: 'medium' },

  // ============ PACKAGING OF DNA HELIX ============
  { id: 'mbi-28', type: 'mcq', question: 'The total length of DNA in a single human cell, if fully stretched out, would be approximately:', options: ['A few micrometres', 'About 2.2 metres', 'A few kilometres', 'A few nanometres'], correctIndex: 1, explanation: 'The total DNA content of a human diploid cell, if fully stretched, measures approximately 2.2 metres, highlighting the need for extensive packaging.', difficulty: 'medium' },
  { id: 'mbi-29', type: 'mcq', question: 'In prokaryotes like E. coli, since a well-defined nucleus is absent, the negatively charged DNA is packaged with the help of positively charged proteins collectively called:', options: ['Histones', 'Nucleoid-associated (HU-like) proteins', 'Enzymatic proteins only', 'Ribosomal proteins'], correctIndex: 1, explanation: 'In prokaryotes, the DNA is held in a region called the nucleoid, packaged with the help of certain positively charged, non-histone proteins.', difficulty: 'medium' },
  { id: 'mbi-30', type: 'mcq', question: 'In eukaryotes, DNA packaging is achieved with the help of positively charged basic proteins called:', options: ['Histones', 'Acidic proteins', 'Enzymes only', 'Nucleoid proteins'], correctIndex: 0, explanation: 'Histones are positively charged basic proteins, rich in the amino acids lysine and arginine, which help package eukaryotic DNA.', difficulty: 'easy' },
  { id: 'mbi-31', type: 'mcq', question: 'Histone proteins are particularly rich in which basic (positively charged) amino acids?', options: ['Lysine and arginine', 'Glycine and alanine', 'Aspartate and glutamate', 'Cysteine and methionine'], correctIndex: 0, explanation: 'Histones are rich in the positively charged basic amino acids lysine and arginine, which help them bind tightly to the negatively charged DNA.', difficulty: 'medium' },
  { id: 'mbi-32', type: 'mcq', question: 'Eight histone molecules organise themselves into a unit called a:', options: ['Nucleosome core', 'Histone octamer', 'Chromatin fibre', 'Solenoid'], correctIndex: 1, explanation: 'Eight histone molecules form a "histone octamer", around which DNA is wrapped to form the nucleosome.', difficulty: 'medium' },
  { id: 'mbi-33', type: 'mcq', question: 'The approximate length of DNA wrapped around a histone octamer to form one nucleosome unit is:', options: ['About 20 base pairs', 'About 200 base pairs', '146 base pairs', '1000 base pairs'], correctIndex: 2, explanation: 'A nucleosome consists of about 146 base pairs of DNA wrapped around a histone octamer.', difficulty: 'medium' },
  { id: 'mbi-34', type: 'mcq', question: 'The repeating unit of chromatin, consisting of DNA wrapped around a histone octamer, is called the:', options: ['Nucleoid', 'Nucleosome', 'Nucleolus', 'Nucleotide chain'], correctIndex: 1, explanation: 'The nucleosome is the fundamental repeating unit of chromatin, giving chromatin its characteristic "beads-on-a-string" appearance under the electron microscope.', difficulty: 'easy' },
  { id: 'mbi-35', type: 'mcq', question: 'Nucleosomes, when observed under an electron microscope, give chromatin the appearance of:', options: ['A smooth, unstructured fibre', 'Beads on a string', 'A solid, compact rod', 'Randomly scattered dots with no pattern'], correctIndex: 1, explanation: 'The repeating nucleosome units give chromatin the characteristic "beads-on-a-string" structure when viewed under an electron microscope.', difficulty: 'medium' },
  { id: 'mbi-36', type: 'mcq', question: 'In addition to the core histones forming the octamer, a linker histone, involved in the compaction of chromatin, is called:', options: ['H1', 'H2A', 'H3', 'H4'], correctIndex: 0, explanation: 'H1 is a linker histone that binds to DNA at the entry and exit points of the nucleosome and helps in further compaction of chromatin.', difficulty: 'medium' },
  { id: 'mbi-37', type: 'mcq', question: 'The regions of chromatin that are loosely packed, appearing lightly stained, are called:', options: ['Heterochromatin', 'Euchromatin', 'Nucleolar chromatin only', 'Sex chromatin exclusively'], correctIndex: 1, explanation: 'Euchromatin is the loosely packed form of chromatin, stains lightly, and is generally considered transcriptionally active.', difficulty: 'medium' },
  { id: 'mbi-38', type: 'mcq', question: 'The regions of chromatin that are densely packed, appearing darkly stained, are called:', options: ['Euchromatin', 'Heterochromatin', 'Free chromatin', 'Nucleosomal chromatin'], correctIndex: 1, explanation: 'Heterochromatin is the densely packed, darkly staining form of chromatin, generally considered transcriptionally inactive.', difficulty: 'medium' },
  { id: 'mbi-39', type: 'assertion', question: 'Assertion (A): Histones, being positively charged, associate strongly with DNA.\nReason (R): DNA is a negatively charged molecule due to its phosphate groups, so the electrostatic attraction between the positively charged histones and negatively charged DNA facilitates tight packaging.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The electrostatic attraction between oppositely charged histones and DNA correctly explains their strong association, matching the assertion.', difficulty: 'medium' },
  { id: 'mbi-40', type: 'assertion', question: 'Assertion (A): Extensive packaging of DNA in the eukaryotic nucleus is essential.\nReason (R): The total length of DNA in a eukaryotic cell vastly exceeds the dimensions of the nucleus, so compaction through histones and higher-order folding is necessary to fit DNA within the nucleus.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The vast disparity between DNA length and nuclear dimensions correctly explains the necessity of extensive DNA packaging.', difficulty: 'medium' },
  { id: 'mbi-41', type: 'count', question: 'Consider the following statements about DNA packaging:\n1. A nucleosome consists of about 146 base pairs of DNA wrapped around a histone octamer.\n2. Histone H1 is one of the core histones forming the histone octamer.\n3. Euchromatin is loosely packed and generally transcriptionally active.\n4. Heterochromatin is densely packed and stains darkly.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — H1 is a linker histone, not one of the core histones forming the octamer.', difficulty: 'medium' },
  { id: 'mbi-42', type: 'matching', question: 'Match Column I (chromatin/DNA packaging term) with Column II (description):\nColumn I: A. Nucleosome  B. Histone octamer  C. Euchromatin  D. Heterochromatin\nColumn II: i. Loosely packed, transcriptionally active  ii. Densely packed, transcriptionally inactive  iii. Eight histone molecules  iv. DNA + histone octamer unit', options: ['A-iv, B-iii, C-i, D-ii', 'A-iii, B-iv, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-i, C-iii, D-ii'], correctIndex: 0, explanation: 'Nucleosome — DNA + histone octamer unit; Histone octamer — eight histone molecules; Euchromatin — loosely packed, active; Heterochromatin — densely packed, inactive.', difficulty: 'medium' },

  // ============ DNA REPLICATION ============
  { id: 'mbi-43', type: 'mcq', question: 'The process by which a DNA molecule produces two identical copies of itself is called:', options: ['Transcription', 'Translation', 'Replication', 'Transformation'], correctIndex: 2, explanation: 'DNA replication is the process by which a DNA molecule is copied to produce two identical daughter DNA molecules.', difficulty: 'easy' },
  { id: 'mbi-44', type: 'mcq', question: 'Watson and Crick, upon proposing the double helix structure, suggested a possible mechanism for DNA replication based on:', options: ['The random, non-complementary joining of bases', 'The complementary nature of the two strands, with each strand acting as a template for a new strand', 'The complete destruction and reassembly of both parental strands', 'A mechanism entirely unrelated to base pairing'], correctIndex: 1, explanation: 'Watson and Crick suggested that each strand of DNA could act as a template for synthesising a new complementary strand, forming the basis of semiconservative replication.', difficulty: 'medium' },
  { id: 'mbi-45', type: 'mcq', question: 'In semiconservative replication, each of the two daughter DNA molecules formed after replication consists of:', options: ['Two newly synthesised strands', 'Two original parental strands', 'One parental (old) strand and one newly synthesised strand', 'A completely random mix of old and new strand segments'], correctIndex: 2, explanation: 'In semiconservative replication, each daughter molecule retains one parental strand and gains one newly synthesised strand.', difficulty: 'easy' },
  { id: 'mbi-46', type: 'mcq', question: 'The classic experiment that provided definitive experimental proof for the semiconservative mode of DNA replication was conducted by:', options: ['Meselson and Stahl', 'Watson and Crick', 'Griffith', 'Hershey and Chase'], correctIndex: 0, explanation: 'Meselson and Stahl (1958) conducted an experiment using E. coli grown in heavy and light isotopes of nitrogen to experimentally confirm the semiconservative mode of DNA replication.', difficulty: 'medium' },
  { id: 'mbi-47', type: 'mcq', question: 'In the Meselson-Stahl experiment, E. coli was first grown in a medium containing which heavy isotope of nitrogen, before being shifted to a medium with the normal light isotope?', options: ['15N', '14N', '13C', '32P'], correctIndex: 0, explanation: 'E. coli was grown for many generations in a medium containing the heavy isotope 15N (heavy nitrogen), before being transferred to normal 14N medium.', difficulty: 'medium' },
  { id: 'mbi-48', type: 'mcq', question: 'Using density gradient centrifugation, Meselson and Stahl observed that after one generation of replication in the light (14N) medium, the DNA formed a band of:', options: ['Pure heavy density, identical to the starting DNA', 'Pure light density, identical to normal 14N DNA', 'Intermediate (hybrid) density, between pure heavy and pure light DNA', 'Two separate bands, one heavy and one light, in equal amounts'], correctIndex: 2, explanation: 'After one generation, the DNA formed a single band of intermediate (hybrid) density, consistent with each daughter molecule having one heavy (old) and one light (new) strand — as predicted by semiconservative replication.', difficulty: 'hard' },
  { id: 'mbi-49', type: 'mcq', question: 'The enzyme primarily responsible for catalysing the polymerisation of new DNA strands during replication is:', options: ['RNA polymerase', 'DNA polymerase', 'DNA ligase alone', 'Reverse transcriptase'], correctIndex: 1, explanation: 'DNA polymerase catalyses the polymerisation of deoxyribonucleotides to synthesise a new DNA strand, using the parental strand as a template.', difficulty: 'easy' },
  { id: 'mbi-50', type: 'mcq', question: 'DNA polymerase can add new nucleotides to a growing DNA strand only in which direction?', options: ['3\' to 5\' direction', '5\' to 3\' direction', 'Bidirectionally, from the middle outward', 'In a random, undirected manner'], correctIndex: 1, explanation: 'DNA polymerases synthesise new DNA strands only in the 5\' to 3\' direction, adding nucleotides to the free 3\'-OH end of the growing chain.', difficulty: 'medium' },
  { id: 'mbi-51', type: 'mcq', question: 'Since DNA polymerase synthesises only in the 5\' to 3\' direction, and the two parental strands are antiparallel, one new strand is synthesised continuously while the other is synthesised discontinuously; the discontinuously synthesised strand is called the:', options: ['Leading strand', 'Lagging strand', 'Template strand only', 'Primary strand'], correctIndex: 1, explanation: 'The lagging strand is synthesised discontinuously, in short fragments called Okazaki fragments, due to the polarity constraint of DNA polymerase.', difficulty: 'medium' },
  { id: 'mbi-52', type: 'mcq', question: 'The continuously synthesised new DNA strand during replication, formed in the same direction as the movement of the replication fork, is called the:', options: ['Leading strand', 'Lagging strand', 'Template strand', 'Okazaki strand'], correctIndex: 0, explanation: 'The leading strand is synthesised continuously in the direction of replication fork movement, requiring only a single priming event.', difficulty: 'medium' },
  { id: 'mbi-53', type: 'mcq', question: 'The short DNA fragments synthesised discontinuously on the lagging strand during replication are called:', options: ['Primers', 'Okazaki fragments', 'Nucleosomes', 'Exons'], correctIndex: 1, explanation: 'Okazaki fragments are the short DNA fragments synthesised discontinuously on the lagging strand, later joined together by DNA ligase.', difficulty: 'medium' },
  { id: 'mbi-54', type: 'mcq', question: 'The enzyme responsible for joining together the Okazaki fragments on the lagging strand, sealing nicks in the sugar-phosphate backbone, is:', options: ['DNA polymerase', 'DNA ligase', 'Helicase', 'Topoisomerase'], correctIndex: 1, explanation: 'DNA ligase catalyses the formation of phosphodiester bonds, joining Okazaki fragments together into a continuous strand.', difficulty: 'medium' },
  { id: 'mbi-55', type: 'mcq', question: 'The enzyme responsible for unwinding the DNA double helix at the replication fork, breaking the hydrogen bonds between base pairs, is called:', options: ['Helicase', 'DNA polymerase', 'DNA ligase', 'Primase'], correctIndex: 0, explanation: 'Helicase unwinds the parental DNA double helix at the replication fork by breaking hydrogen bonds between complementary base pairs.', difficulty: 'medium' },
  { id: 'mbi-56', type: 'mcq', question: 'DNA polymerase cannot initiate synthesis of a new DNA strand on its own and requires a short stretch of RNA, called a primer, synthesised by the enzyme:', options: ['Primase (an RNA polymerase)', 'Helicase', 'Topoisomerase', 'Ligase'], correctIndex: 0, explanation: 'Primase, a type of RNA polymerase, synthesises a short RNA primer that provides a free 3\'-OH group for DNA polymerase to begin DNA synthesis.', difficulty: 'medium' },
  { id: 'mbi-57', type: 'mcq', question: 'The specific site on the DNA where replication begins is called the:', options: ['Terminator', 'Origin of replication', 'Promoter', 'Operator'], correctIndex: 1, explanation: 'Replication begins at a specific nucleotide sequence called the origin of replication.', difficulty: 'medium' },
  { id: 'mbi-58', type: 'mcq', question: 'In bacteria such as E. coli, replication of the circular chromosome occurs from:', options: ['A single, defined origin of replication', 'Multiple, randomly scattered origins throughout the genome', 'No specific origin; replication starts anywhere randomly', 'Only from the termination point'], correctIndex: 0, explanation: 'In bacteria, replication begins from a single, well-defined origin of replication on the circular chromosome.', difficulty: 'medium' },
  { id: 'mbi-59', type: 'assertion', question: 'Assertion (A): Lagging strand synthesis requires multiple RNA primers, unlike leading strand synthesis.\nReason (R): Since the lagging strand is synthesised discontinuously in short fragments (Okazaki fragments), each fragment requires its own separate RNA primer for initiation by DNA polymerase.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The discontinuous nature of lagging strand synthesis, requiring separate initiation for each Okazaki fragment, correctly explains the need for multiple primers.', difficulty: 'hard' },
  { id: 'mbi-60', type: 'assertion', question: 'Assertion (A): DNA replication is termed "semiconservative" rather than "conservative" or "dispersive".\nReason (R): Each daughter DNA molecule, after one round of replication, contains one intact parental strand and one newly synthesised strand, as demonstrated by the Meselson-Stahl experiment.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The experimentally confirmed pattern of one old and one new strand per daughter molecule correctly explains why the mode is termed semiconservative.', difficulty: 'medium' },
  { id: 'mbi-61', type: 'count', question: 'Consider the following statements about DNA replication:\n1. DNA polymerase synthesises new DNA strands in the 5\' to 3\' direction only.\n2. The leading strand is synthesised discontinuously in short fragments.\n3. Okazaki fragments are joined together by DNA ligase.\n4. Helicase is responsible for unwinding the DNA double helix during replication.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — it is the lagging strand, not the leading strand, that is synthesised discontinuously.', difficulty: 'medium' },
  { id: 'mbi-62', type: 'count', question: 'Consider the following statements about the Meselson-Stahl experiment:\n1. E. coli was initially grown in a medium containing heavy nitrogen (15N).\n2. After one generation in light (14N) medium, DNA appeared as a hybrid (intermediate) density band.\n3. The results supported the conservative mode of replication.\n4. The results were obtained using density gradient centrifugation.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the results supported the semiconservative mode of replication, not the conservative mode.', difficulty: 'medium' },
  { id: 'mbi-63', type: 'statement', question: 'Statement I: DNA replication requires an RNA primer to initiate synthesis of a new DNA strand.\nStatement II: This primer is later removed and replaced with DNA, with the gaps sealed by DNA ligase.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly describes the fate of the primer mentioned in Statement I', 'Both statements are correct but unrelated', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'The RNA primer described in Statement I is indeed later replaced by DNA polymerase and sealed by ligase, as correctly described in Statement II.', difficulty: 'medium' },
  { id: 'mbi-64', type: 'matching', question: 'Match Column I (enzyme) with Column II (function during replication):\nColumn I: A. Helicase  B. Primase  C. DNA polymerase  D. DNA ligase\nColumn II: i. Synthesises RNA primer  ii. Joins Okazaki fragments  iii. Unwinds the double helix  iv. Polymerises new DNA strand', options: ['A-iii, B-i, C-iv, D-ii', 'A-i, B-iii, C-ii, D-iv', 'A-iv, B-ii, C-i, D-iii', 'A-iii, B-iv, C-i, D-ii'], correctIndex: 0, explanation: 'Helicase — unwinds the helix; Primase — synthesises RNA primer; DNA polymerase — polymerises new strand; DNA ligase — joins Okazaki fragments.', difficulty: 'medium' },

  // ============ TRANSCRIPTION ============
  { id: 'mbi-65', type: 'mcq', question: 'The process by which genetic information encoded in DNA is copied into a complementary RNA molecule is called:', options: ['Replication', 'Transcription', 'Translation', 'Reverse transcription'], correctIndex: 1, explanation: 'Transcription is the process of copying genetic information from one strand of DNA into RNA.', difficulty: 'easy' },
  { id: 'mbi-66', type: 'mcq', question: 'During transcription, only a segment of DNA and only one of the two strands is used as a template; this template strand is also called the:', options: ['Coding strand', 'Template (antisense) strand', 'Sense strand', 'Both strands equally, without distinction'], correctIndex: 1, explanation: 'The strand that serves as a template for RNA synthesis is called the template or antisense strand, since RNA is synthesised complementary to it.', difficulty: 'medium' },
  { id: 'mbi-67', type: 'mcq', question: 'The DNA strand that has the same sequence (except thymine replaced by uracil) as the RNA transcript, and does NOT act as a template, is called the:', options: ['Template strand', 'Coding (sense) strand', 'Antisense strand', 'Palindromic strand'], correctIndex: 1, explanation: 'The coding (sense) strand has the same base sequence as the RNA transcript (with T replaced by U), while the complementary antisense/template strand is actually copied.', difficulty: 'medium' },
  { id: 'mbi-68', type: 'mcq', question: 'The enzyme responsible for catalysing the synthesis of RNA using a DNA template during transcription is called:', options: ['DNA polymerase', 'RNA polymerase', 'DNA ligase', 'Reverse transcriptase'], correctIndex: 1, explanation: 'RNA polymerase catalyses the process of transcription, synthesising RNA using DNA as a template.', difficulty: 'easy' },
  { id: 'mbi-69', type: 'mcq', question: 'The specific DNA sequence to which RNA polymerase binds to initiate transcription is called the:', options: ['Terminator', 'Promoter', 'Operator', 'Origin'], correctIndex: 1, explanation: 'The promoter is a specific DNA sequence, generally located upstream, that provides the binding site for RNA polymerase, defining the start point and direction of transcription.', difficulty: 'medium' },
  { id: 'mbi-70', type: 'mcq', question: 'The specific DNA sequence that defines the end point of the transcription process is called the:', options: ['Promoter', 'Terminator', 'Enhancer', 'Origin'], correctIndex: 1, explanation: 'The terminator sequence, located at the end of the transcription unit, defines the point at which RNA polymerase stops transcription.', difficulty: 'medium' },
  { id: 'mbi-71', type: 'mcq', question: 'A complete transcription unit in DNA is defined by three components: a promoter, the structural gene, and a:', options: ['Terminator', 'Second promoter', 'Origin of replication', 'Ribosome binding site only'], correctIndex: 0, explanation: 'A transcription unit consists of a promoter, the structural gene(s), and a terminator, together defining the segment of DNA that is transcribed.', difficulty: 'medium' },
  { id: 'mbi-72', type: 'mcq', question: 'In eukaryotes, the enzyme responsible for transcribing precursor mRNA (hnRNA), which will later become mature mRNA, is:', options: ['RNA polymerase I', 'RNA polymerase II', 'RNA polymerase III', 'DNA polymerase I'], correctIndex: 1, explanation: 'RNA polymerase II transcribes precursor mRNA (heterogeneous nuclear RNA, hnRNA) in eukaryotes, which is processed to form mature mRNA.', difficulty: 'medium' },
  { id: 'mbi-73', type: 'mcq', question: 'In eukaryotes, RNA polymerase I is responsible for transcribing:', options: ['Precursor mRNA (hnRNA)', 'The precursor for rRNAs (ribosomal RNA)', 'tRNA and other small RNAs', 'None of the RNA classes'], correctIndex: 1, explanation: 'RNA polymerase I transcribes ribosomal RNA (rRNA) precursors in the eukaryotic nucleolus.', difficulty: 'medium' },
  { id: 'mbi-74', type: 'mcq', question: 'In eukaryotes, RNA polymerase III is responsible for transcribing:', options: ['Precursor mRNA (hnRNA)', 'rRNA precursor', 'tRNA, 5S rRNA, and other small RNAs', 'None of the RNA classes'], correctIndex: 2, explanation: 'RNA polymerase III transcribes small RNAs such as tRNA and 5S rRNA in eukaryotic cells.', difficulty: 'medium' },
  { id: 'mbi-75', type: 'mcq', question: 'In prokaryotes, unlike eukaryotes, all three types of RNA (mRNA, tRNA and rRNA) are transcribed by:', options: ['Three different RNA polymerases, exactly as in eukaryotes', 'A single type of RNA polymerase', 'DNA polymerase alone, without any RNA polymerase', 'No enzyme is required, since transcription is non-enzymatic'], correctIndex: 1, explanation: 'In prokaryotes, a single RNA polymerase is responsible for the synthesis of all types of RNA, unlike eukaryotes, which have three distinct RNA polymerases.', difficulty: 'medium' },
  { id: 'mbi-76', type: 'mcq', question: 'Unlike DNA replication, transcription in a cell involves the copying of:', options: ['The entire DNA molecule at once', 'Only a specific segment of DNA, corresponding to a particular gene', 'Only the sense strand throughout the genome', 'Neither strand of DNA in any part of the genome'], correctIndex: 1, explanation: 'Transcription selectively copies only specific segments of DNA (genes), rather than the entire genome, unlike replication which copies the whole DNA molecule.', difficulty: 'medium' },
  { id: 'mbi-77', type: 'mcq', question: 'The heterogeneous nuclear RNA (hnRNA) produced by RNA polymerase II in eukaryotes must undergo processing before becoming functional mRNA; this processing includes:', options: ['Splicing only, with no other modifications', 'Capping, tailing and splicing', 'Only degradation, with no export from the nucleus', 'Direct translation without any processing'], correctIndex: 1, explanation: 'The primary transcript (hnRNA) undergoes capping (at the 5\' end), tailing (poly-A addition at the 3\' end), and splicing (removal of introns) to become mature mRNA.', difficulty: 'medium' },
  { id: 'mbi-78', type: 'mcq', question: 'Splicing, one of the key steps in mRNA processing, involves:', options: ['Removal of introns (non-coding sequences) and joining together of exons (coding sequences)', 'Addition of a cap structure at the 5\' end only', 'Addition of a poly-A tail at the 3\' end only', 'Complete degradation of the mRNA transcript'], correctIndex: 0, explanation: 'Splicing removes non-coding intervening sequences (introns) and joins together the coding sequences (exons) to form the mature, functional mRNA.', difficulty: 'medium' },
  { id: 'mbi-79', type: 'mcq', question: 'The addition of an unusual nucleotide (methylated guanosine) to the 5\' end of the hnRNA, an early step in mRNA processing, is called:', options: ['Tailing', 'Capping', 'Splicing', 'Editing'], correctIndex: 1, explanation: 'Capping refers to the addition of a methyl guanosine triphosphate cap structure at the 5\' end of the hnRNA.', difficulty: 'medium' },
  { id: 'mbi-80', type: 'mcq', question: 'The addition of adenylate residues at the 3\' end of the hnRNA in a template-independent manner is called:', options: ['Capping', 'Tailing (poly-adenylation)', 'Splicing', 'Editing'], correctIndex: 1, explanation: 'Tailing refers to the addition of 200–300 adenylate residues at the 3\' end of the hnRNA, forming the poly-A tail, in a template-independent manner.', difficulty: 'medium' },
  { id: 'mbi-81', type: 'assertion', question: 'Assertion (A): The primary transcript in eukaryotes is not directly functional and must undergo processing.\nReason (R): The primary transcript (hnRNA) contains both exons (coding sequences) and introns (non-coding sequences), which must be processed through capping, tailing and splicing to produce a mature, translatable mRNA.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The presence of introns requiring removal, along with the need for capping and tailing, correctly explains why the primary transcript must be processed before functioning as mature mRNA.', difficulty: 'medium' },
  { id: 'mbi-82', type: 'assertion', question: 'Assertion (A): Prokaryotic mRNA does not require extensive processing, unlike eukaryotic mRNA.\nReason (R): In prokaryotes, since there is no physical separation of transcription and translation (both occur in the cytoplasm), and genes generally lack introns, translation can begin even while transcription is still in progress.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The lack of nuclear compartmentalisation and general absence of introns in prokaryotic genes correctly explains why extensive mRNA processing is not required.', difficulty: 'hard' },
  { id: 'mbi-83', type: 'count', question: 'Consider the following statements about transcription:\n1. RNA polymerase synthesises RNA using DNA as a template.\n2. The promoter defines where transcription begins.\n3. In eukaryotes, a single RNA polymerase transcribes all types of RNA, exactly as in prokaryotes.\n4. hnRNA undergoes splicing, capping and tailing to form mature mRNA.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — eukaryotes use three different RNA polymerases (I, II and III), unlike prokaryotes, which use only one.', difficulty: 'medium' },
  { id: 'mbi-84', type: 'count', question: 'Consider the following statements about mRNA processing:\n1. Capping involves addition of a modified nucleotide at the 5\' end of hnRNA.\n2. Tailing involves addition of adenylate residues at the 3\' end of hnRNA.\n3. Splicing involves removal of exons and retention of introns.\n4. All three modifications (capping, tailing, splicing) occur in the cytoplasm, not the nucleus.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statement 3 is reversed (introns are removed, exons retained), and statement 4 is wrong — these processes occur in the nucleus of eukaryotic cells, not the cytoplasm.', difficulty: 'hard' },
  { id: 'mbi-85', type: 'statement', question: 'Statement I: Exons are the coding sequences of a gene that are retained in the mature mRNA.\nStatement II: Introns are non-coding intervening sequences that are removed during RNA splicing.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly define exons (retained, coding) and introns (removed, non-coding) in the context of RNA splicing.', difficulty: 'easy' },
  { id: 'mbi-86', type: 'matching', question: 'Match Column I (RNA polymerase, eukaryotic) with Column II (RNA transcribed):\nColumn I: A. RNA polymerase I  B. RNA polymerase II  C. RNA polymerase III\nColumn II: i. tRNA, 5S rRNA  ii. Precursor mRNA (hnRNA)  iii. rRNA precursor', options: ['A-iii, B-ii, C-i', 'A-i, B-ii, C-iii', 'A-ii, B-iii, C-i', 'A-iii, B-i, C-ii'], correctIndex: 0, explanation: 'RNA polymerase I — rRNA precursor; RNA polymerase II — precursor mRNA; RNA polymerase III — tRNA and 5S rRNA.', difficulty: 'medium' },

  // ============ GENETIC CODE ============
  { id: 'mbi-87', type: 'mcq', question: 'The genetic code refers to the relationship between the sequence of bases in mRNA and the sequence of:', options: ['Nucleotides in DNA', 'Amino acids in the protein synthesised', 'Ribosomal subunits', 'Nitrogenous bases in tRNA only'], correctIndex: 1, explanation: 'The genetic code defines the specific correspondence between the sequence of nucleotide bases in mRNA (read as codons) and the sequence of amino acids in the resulting protein.', difficulty: 'easy' },
  { id: 'mbi-88', type: 'mcq', question: 'A single unit of the genetic code, consisting of a specific sequence of three consecutive nitrogenous bases in mRNA, is called a:', options: ['Codon', 'Anticodon', 'Exon', 'Cistron'], correctIndex: 0, explanation: 'A codon is a triplet (three consecutive bases) in mRNA that codes for a specific amino acid or acts as a stop signal.', difficulty: 'easy' },
  { id: 'mbi-89', type: 'mcq', question: 'The genetic code was deciphered largely through the pioneering experiments of which scientists, using synthetic RNA polymers?', options: ['Watson and Crick', 'Har Gobind Khorana and Marshall Nirenberg', 'Griffith and Avery', 'Meselson and Stahl'], correctIndex: 1, explanation: 'Har Gobind Khorana and Marshall Nirenberg, among others, played key roles in deciphering the genetic code through experiments using synthetic RNA templates.', difficulty: 'medium' },
  { id: 'mbi-90', type: 'mcq', question: 'Since there are 4 different bases and codons consist of triplets, the total number of possible codons in the genetic code is:', options: ['4', '16', '64', '20'], correctIndex: 2, explanation: 'With 4 bases forming codons of 3 nucleotides each, the total possible number of codons is 4^3 = 64.', difficulty: 'medium' },
  { id: 'mbi-91', type: 'mcq', question: 'Of the 64 possible codons, how many actually code for specific amino acids (sense codons)?', options: ['64', '61', '20', '3'], correctIndex: 1, explanation: '61 of the 64 codons code for amino acids (sense codons), while the remaining 3 act as stop (nonsense) codons.', difficulty: 'medium' },
  { id: 'mbi-92', type: 'mcq', question: 'The three codons that do not code for any amino acid, but instead signal the termination of translation, are collectively called:', options: ['Sense codons', 'Stop (nonsense/termination) codons', 'Start codons', 'Silent codons'], correctIndex: 1, explanation: 'The three stop codons (UAA, UAG, UGA) do not code for any amino acid but signal the termination of protein synthesis.', difficulty: 'medium' },
  { id: 'mbi-93', type: 'mcq', question: 'The codon that typically signals the initiation of protein synthesis (start codon) is:', options: ['UAA', 'UGA', 'AUG', 'UAG'], correctIndex: 2, explanation: 'AUG is the start codon, which codes for methionine and also signals the beginning of translation.', difficulty: 'easy' },
  { id: 'mbi-94', type: 'mcq', question: 'Since more than one codon can specify the same amino acid, the genetic code is said to be:', options: ['Ambiguous', 'Degenerate', 'Non-overlapping', 'Universal'], correctIndex: 1, explanation: 'The genetic code is degenerate, meaning some amino acids are coded by more than one codon (e.g., leucine and serine are each coded by six codons).', difficulty: 'medium' },
  { id: 'mbi-95', type: 'mcq', question: 'The genetic code is said to be "unambiguous" because:', options: ['A single codon codes for more than one amino acid', 'A specific codon always codes for the same amino acid, without exception', 'Codons overlap with each other for efficient use of sequence', 'Every codon is read differently in different organisms'], correctIndex: 1, explanation: 'Unambiguous means that a particular codon always codes for the same amino acid, and does not have multiple meanings within the same organism.', difficulty: 'medium' },
  { id: 'mbi-96', type: 'mcq', question: 'The genetic code is described as "universal" because:', options: ['The codon assignments are essentially the same, from bacteria to humans, with rare exceptions', 'Different organisms use completely different codes to specify amino acids', 'Only prokaryotes share the same genetic code', 'Codons vary randomly between individuals of the same species'], correctIndex: 0, explanation: 'The universality of the genetic code refers to the fact that a given codon specifies the same amino acid in almost all organisms, from bacteria to humans, with a few exceptions.', difficulty: 'medium' },
  { id: 'mbi-97', type: 'mcq', question: 'The genetic code is read in a continuous manner, without any punctuation between successive codons, once translation starts at a fixed start point; this property is described as:', options: ['Overlapping', 'Non-overlapping and comma-less', 'Ambiguous', 'Redundant only'], correctIndex: 1, explanation: 'The genetic code is read as a continuous sequence of triplets from a fixed starting point, without overlap or "punctuation" (commas) between codons.', difficulty: 'medium' },
  { id: 'mbi-98', type: 'mcq', question: 'The phenomenon in which the third base of some codons can vary (wobble) without changing the amino acid specified, allowing a single tRNA to recognise more than one codon, is called:', options: ['The wobble hypothesis', 'The universal code hypothesis', 'The overlapping code hypothesis', 'The degeneracy exclusion principle'], correctIndex: 0, explanation: 'The wobble hypothesis explains how flexibility at the third codon position allows a single tRNA to pair with more than one codon specifying the same amino acid.', difficulty: 'hard' },
  { id: 'mbi-99', type: 'assertion', question: 'Assertion (A): The degeneracy of the genetic code provides a buffer against the harmful effects of certain point mutations.\nReason (R): Since multiple codons can specify the same amino acid, a mutation altering the third base of a codon (in many cases) does not change the amino acid incorporated into the protein, due to the wobble effect.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The wobble effect, allowing tolerance of certain third-base mutations without changing the resultant amino acid, correctly explains the protective (buffering) role of code degeneracy.', difficulty: 'hard' },
  { id: 'mbi-100', type: 'assertion', question: 'Assertion (A): The universality of the genetic code has practical significance in modern biotechnology.\nReason (R): Since the codon assignments are essentially the same across organisms, a gene from one species (e.g., human insulin gene) can be expressed correctly in a different organism (e.g., bacteria).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The near-universal nature of codon assignments correctly explains why genes can be transferred and expressed across different species, a key principle underlying recombinant DNA technology.', difficulty: 'medium' },
  { id: 'mbi-101', type: 'count', question: 'Consider the following statements about the genetic code:\n1. There are a total of 64 possible codons.\n2. Of these, 61 codons specify amino acids, and 3 are stop codons.\n3. AUG codes only as a start codon and never for any amino acid within the protein sequence.\n4. The genetic code is degenerate, meaning some amino acids are specified by more than one codon.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — AUG also codes for methionine at internal positions within a protein, not solely as a start signal.', difficulty: 'hard' },
  { id: 'mbi-102', type: 'count', question: 'Consider the following properties attributed to the genetic code:\n1. Degenerate\n2. Unambiguous\n3. Overlapping\n4. Universal\n5. Ambiguous\nHow many of the above are correctly recognised properties of the genetic code?', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 1, explanation: 'Degenerate, unambiguous and universal are correctly recognised properties of the genetic code. The code is non-overlapping (not overlapping) and unambiguous (not ambiguous), so those two are incorrect as stated.', difficulty: 'hard' },
  { id: 'mbi-103', type: 'statement', question: 'Statement I: The genetic code is read as non-overlapping triplets from a fixed starting point.\nStatement II: This means that each base in the mRNA sequence is used only once, as part of a single codon, during the reading of a particular reading frame.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct, and Statement II correctly elaborates on Statement I', 'Both statements are correct but unrelated', 'Statement I is correct, Statement II is incorrect', 'Statement I is incorrect, Statement II is correct'], correctIndex: 0, explanation: 'The non-overlapping nature described in Statement I is accurately elaborated by Statement II, which explains that each base belongs to only one codon within a given reading frame.', difficulty: 'medium' },

  // ============ tRNA — THE ADAPTER MOLECULE ============
  { id: 'mbi-104', type: 'mcq', question: 'The molecule that acts as an "adapter" during translation, reading the codon on mRNA on one end while carrying the corresponding amino acid on the other, is:', options: ['mRNA', 'tRNA', 'rRNA', 'DNA'], correctIndex: 1, explanation: 'tRNA (transfer RNA) acts as an adapter molecule, translating the language of nucleic acids into the language of proteins by matching codons to amino acids.', difficulty: 'easy' },
  { id: 'mbi-105', type: 'mcq', question: 'The characteristic two-dimensional structure of tRNA, resembling a cloverleaf due to intramolecular base pairing, is called the:', options: ['Cloverleaf structure', 'Double helix structure', 'Beta-pleated structure', 'Octamer structure'], correctIndex: 0, explanation: 'tRNA folds into a characteristic cloverleaf structure in two dimensions, due to complementary base pairing within the molecule.', difficulty: 'medium' },
  { id: 'mbi-106', type: 'mcq', question: 'The three-nucleotide sequence on tRNA that is complementary to the codon on mRNA, allowing specific recognition, is called the:', options: ['Codon', 'Anticodon', 'Acceptor stem', 'Wobble site'], correctIndex: 1, explanation: 'The anticodon is the three-nucleotide sequence on tRNA that base-pairs with the complementary codon on mRNA during translation.', difficulty: 'medium' },
  { id: 'mbi-107', type: 'mcq', question: 'The specific amino acid corresponding to a particular tRNA molecule attaches to the tRNA at its:', options: ['Anticodon loop', '3\' end (acceptor arm)', '5\' end exclusively, with no association to the 3\' end', 'D-loop only'], correctIndex: 1, explanation: 'The amino acid attaches to the tRNA at its 3\' end, in the region known as the acceptor arm.', difficulty: 'medium' },
  { id: 'mbi-108', type: 'assertion', question: 'Assertion (A): tRNA is described as an "adapter" molecule in the process of translation.\nReason (R): tRNA physically links the nucleotide-based codon sequence on mRNA to the specific amino acid it corresponds to, bridging the "language" of nucleic acids and proteins.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The role of tRNA in linking codon sequence to specific amino acid correctly explains why it is described as an adapter molecule.', difficulty: 'medium' },
  { id: 'mbi-109', type: 'count', question: 'Consider the following statements about tRNA:\n1. tRNA has a characteristic cloverleaf secondary structure.\n2. The anticodon of a tRNA is complementary to the codon on mRNA.\n3. Amino acids attach to tRNA at the anticodon loop.\n4. tRNA plays a role in translation but has no role in the initiation of protein synthesis.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statement 3 is wrong (amino acids attach at the acceptor arm/3\' end, not the anticodon loop), and statement 4 is wrong (a special initiator tRNA is essential for translation initiation).', difficulty: 'medium' },

  // ============ TRANSLATION ============
  { id: 'mbi-110', type: 'mcq', question: 'The process by which the sequence of codons in mRNA is used to synthesise a polypeptide chain (protein) is called:', options: ['Transcription', 'Translation', 'Replication', 'Transformation'], correctIndex: 1, explanation: 'Translation is the process of polymerising amino acids to form a polypeptide, based on the sequence of codons carried by mRNA.', difficulty: 'easy' },
  { id: 'mbi-111', type: 'mcq', question: 'The order of amino acids in a protein is determined directly by the order of:', options: ['Bases in DNA only, without reference to mRNA', 'Codons in mRNA', 'Nucleosomes along the chromosome', 'Ribosomal proteins'], correctIndex: 1, explanation: 'The sequence of codons in mRNA directly determines the order in which amino acids are added during translation.', difficulty: 'easy' },
  { id: 'mbi-112', type: 'mcq', question: 'The cellular machinery on which translation physically occurs, consisting of rRNA and associated proteins, is called the:', options: ['Nucleus', 'Ribosome', 'Golgi apparatus', 'Endoplasmic reticulum only'], correctIndex: 1, explanation: 'The ribosome is the cellular machinery that facilitates translation, moving along the mRNA and catalysing peptide bond formation.', difficulty: 'easy' },
  { id: 'mbi-113', type: 'mcq', question: 'A ribosome, in its inactive state, exists as two separate subunits; these subunits associate to become an active translating ribosome upon:', options: ['Binding to mRNA', 'Formation of DNA polymerase complexes', 'Random collision in the cytoplasm, without any specific trigger', 'Fusion with the nuclear envelope'], correctIndex: 0, explanation: 'When not translating, the ribosome exists as two subunits; these come together on an mRNA molecule at the start of translation to form the functional ribosome.', difficulty: 'medium' },
  { id: 'mbi-114', type: 'mcq', question: 'A ribosome possesses two sites for binding aminoacyl-tRNA molecules during the process of translation, in addition to a site for binding the initiator tRNA; these are collectively called the:', options: ['A (aminoacyl) site and P (peptidyl) site', 'Promoter site and terminator site', 'Cap site and tail site', 'Sense site and antisense site'], correctIndex: 0, explanation: 'The ribosome has an A (aminoacyl) site for incoming charged tRNA and a P (peptidyl) site for the tRNA carrying the growing polypeptide chain.', difficulty: 'medium' },
  { id: 'mbi-115', type: 'mcq', question: 'The energy required for various steps during protein synthesis, such as aminoacylation of tRNA and ribosome translocation, is generally provided by hydrolysis of:', options: ['ATP and GTP', 'Only NADH', 'Only FADH2', 'DNA nucleotides only'], correctIndex: 0, explanation: 'Various steps in translation, including tRNA charging and ribosome movement, are energy-dependent processes fuelled by ATP and GTP hydrolysis.', difficulty: 'medium' },
  { id: 'mbi-116', type: 'mcq', question: 'The process of translation can be conceptually divided into three main stages:', options: ['Initiation, elongation and termination', 'Capping, tailing and splicing', 'Replication, transcription and translation', 'Transformation, translation and transduction'], correctIndex: 0, explanation: 'Translation occurs in three main stages: initiation (ribosome assembly at the start codon), elongation (addition of amino acids), and termination (release of the polypeptide).', difficulty: 'easy' },
  { id: 'mbi-117', type: 'mcq', question: 'Translation is initiated at the start codon, which corresponds to the amino acid:', options: ['Glycine', 'Methionine', 'Alanine', 'Tryptophan'], correctIndex: 1, explanation: 'The start codon AUG corresponds to methionine, which is the first amino acid incorporated (in eukaryotes) at the initiation of translation.', difficulty: 'easy' },
  { id: 'mbi-118', type: 'mcq', question: 'Translation continues in the elongation stage as the ribosome moves along the mRNA, adding amino acids one by one, until it reaches:', options: ['A specific enhancer sequence', 'One of the stop codons', 'The origin of replication', 'The promoter sequence again'], correctIndex: 1, explanation: 'Elongation continues until the ribosome encounters a stop codon (UAA, UAG or UGA) in the mRNA, signalling termination.', difficulty: 'medium' },
  { id: 'mbi-119', type: 'mcq', question: 'Since stop codons do not code for any amino acid, and no tRNA has an anticodon that recognises them, the arrival of a stop codon at the ribosomal A site leads to:', options: ['Binding of release factors and termination of translation, releasing the polypeptide', 'Continued elongation, skipping the stop codon', 'Immediate destruction of the ribosome', 'Reversal of translation direction'], correctIndex: 0, explanation: 'Release factors bind to the ribosome when a stop codon is encountered, terminating translation and releasing the completed polypeptide.', difficulty: 'medium' },
  { id: 'mbi-120', type: 'assertion', question: 'Assertion (A): Translation is a highly coordinated and energy-intensive cellular process.\nReason (R): Multiple discrete steps — including ribosome assembly, tRNA charging, and codon-anticodon recognition at each step of elongation — must occur precisely and are fuelled by hydrolysis of high-energy phosphate bonds (ATP/GTP).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The multiple, precisely coordinated, energy-requiring steps involved in translation correctly explain why the overall process is described as coordinated and energy-intensive.', difficulty: 'medium' },
  { id: 'mbi-121', type: 'count', question: 'Consider the following statements about translation:\n1. Translation occurs on ribosomes, composed of rRNA and proteins.\n2. The A site of the ribosome is where the initiator tRNA first binds, exclusively.\n3. Elongation continues until a stop codon is encountered.\n4. Release factors are involved in terminating translation at a stop codon.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — the initiator tRNA generally binds at the P site, not the A site, during initiation.', difficulty: 'hard' },
  { id: 'mbi-122', type: 'statement', question: 'Statement I: Ribosomes lack the ability to directly "read" the mRNA sequence themselves; they rely on tRNA to match codons with amino acids.\nStatement II: Ribosomes function as the site where amino acids are joined together by peptide bonds during translation.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements accurately describe the functional roles of tRNA (codon reading via base pairing) and the ribosome (site of peptide bond formation) during translation.', difficulty: 'medium' },
  { id: 'mbi-123', type: 'matching', question: 'Match Column I (translation-related term) with Column II (description):\nColumn I: A. Start codon  B. Stop codon  C. A site  D. P site\nColumn II: i. Where the growing peptidyl-tRNA is located  ii. Where incoming aminoacyl-tRNA binds  iii. Signals initiation, codes for methionine  iv. Signals termination, no corresponding tRNA', options: ['A-iii, B-iv, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-i, D-ii', 'A-iii, B-i, C-iv, D-ii'], correctIndex: 0, explanation: 'Start codon — initiation, methionine; Stop codon — termination, no tRNA; A site — incoming aminoacyl-tRNA; P site — peptidyl-tRNA.', difficulty: 'medium' },

  // ============ REGULATION OF GENE EXPRESSION: THE LAC OPERON ============
  { id: 'mbi-124', type: 'mcq', question: 'The process by which a cell controls whether or not a particular gene is expressed, and to what level, is called:', options: ['Gene expression regulation', 'DNA replication control', 'Chromosomal aberration', 'Codon degeneracy'], correctIndex: 0, explanation: 'Regulation of gene expression refers to the mechanisms by which cells control the timing, location and level of expression of a particular gene.', difficulty: 'easy' },
  { id: 'mbi-125', type: 'mcq', question: 'The classic model system used to study the regulation of gene expression in prokaryotes, involving genes for lactose metabolism in E. coli, is called the:', options: ['Trp operon', 'Lac operon', 'His operon', 'Ara operon'], correctIndex: 1, explanation: 'The lac operon, involving genes for lactose metabolism in E. coli, is the classic model system used to explain the mechanism of gene regulation, proposed by Jacob and Monod.', difficulty: 'medium' },
  { id: 'mbi-126', type: 'mcq', question: 'The lac operon model of gene regulation in E. coli was proposed by:', options: ['Jacob and Monod', 'Watson and Crick', 'Meselson and Stahl', 'Avery and MacLeod'], correctIndex: 0, explanation: 'Francois Jacob and Jacques Monod proposed the operon model to explain the regulation of the lac genes in E. coli.', difficulty: 'medium' },
  { id: 'mbi-127', type: 'mcq', question: 'A cluster of genes under the control of a single promoter, regulated together as a single functional unit, as seen in prokaryotic gene organisation, is called an:', options: ['Exon cluster', 'Operon', 'Intron cluster', 'Nucleosome cluster'], correctIndex: 1, explanation: 'An operon is a cluster of structural genes under the control of a single promoter, transcribed together as a single mRNA.', difficulty: 'medium' },
  { id: 'mbi-128', type: 'mcq', question: 'The lac operon of E. coli consists of one regulatory gene (i) and how many structural genes involved in lactose metabolism?', options: ['One structural gene', 'Two structural genes', 'Three structural genes (z, y, a)', 'Five structural genes'], correctIndex: 2, explanation: 'The lac operon has three structural genes: z (beta-galactosidase), y (permease), and a (transacetylase), along with the regulatory "i" gene.', difficulty: 'medium' },
  { id: 'mbi-129', type: 'mcq', question: 'The "i" gene of the lac operon codes for:', options: ['Beta-galactosidase enzyme', 'A repressor protein that controls the transcription of the structural genes', 'Permease enzyme', 'Transacetylase enzyme'], correctIndex: 1, explanation: 'The "i" gene codes for the repressor protein, which regulates transcription of the structural genes (z, y, a) by binding to the operator region.', difficulty: 'medium' },
  { id: 'mbi-130', type: 'mcq', question: 'In the absence of lactose (the inducer), the repressor protein of the lac operon:', options: ['Binds to the operator region, preventing RNA polymerase from transcribing the structural genes', 'Is degraded immediately', 'Binds directly to the structural genes, activating transcription', 'Has no effect on transcription at all'], correctIndex: 0, explanation: 'In the absence of lactose, the repressor binds to the operator region, blocking RNA polymerase and preventing transcription of the structural genes.', difficulty: 'medium' },
  { id: 'mbi-131', type: 'mcq', question: 'In the presence of lactose, the inducer molecule (allolactose, a derivative of lactose) binds to the repressor protein, causing the repressor to:', options: ['Bind even more tightly to the operator', 'Undergo a conformational change and detach from the operator, allowing transcription', 'Be permanently destroyed within the cell', 'Directly synthesise new mRNA'], correctIndex: 1, explanation: 'When lactose (via its derivative allolactose) binds to the repressor, the repressor changes shape and can no longer bind the operator, allowing RNA polymerase to transcribe the structural genes.', difficulty: 'medium' },
  { id: 'mbi-132', type: 'mcq', question: 'The beta-galactosidase enzyme, encoded by the z gene of the lac operon, functions to:', options: ['Transport lactose into the cell', 'Hydrolyse lactose into glucose and galactose', 'Transfer an acetyl group to certain compounds', 'Repress transcription of the operon'], correctIndex: 1, explanation: 'Beta-galactosidase, encoded by the z gene, hydrolyses lactose into its constituent monosaccharides, glucose and galactose.', difficulty: 'medium' },
  { id: 'mbi-133', type: 'mcq', question: 'The y gene of the lac operon encodes an enzyme (permease) that primarily functions to:', options: ['Hydrolyse lactose', 'Increase the permeability of the cell to allow entry of lactose', 'Transfer acetyl groups to certain molecules', 'Serve as the operon\'s repressor'], correctIndex: 1, explanation: 'Permease, encoded by the y gene, increases the permeability of the bacterial cell, facilitating the entry of lactose from the environment.', difficulty: 'medium' },
  { id: 'mbi-134', type: 'assertion', question: 'Assertion (A): The lac operon is described as an "inducible" operon.\nReason (R): The structural genes of the lac operon are normally kept switched off, and are turned on ("induced") specifically in the presence of lactose (the inducer).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The requirement of an inducer molecule (lactose) to switch on transcription correctly explains why the lac operon is termed "inducible".', difficulty: 'medium' },
  { id: 'mbi-135', type: 'assertion', question: 'Assertion (A): Regulation of gene expression allows bacteria to conserve energy and resources.\nReason (R): By expressing genes such as those of the lac operon only when the substrate (lactose) is present, bacteria avoid the unnecessary synthesis of enzymes when they are not needed.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The conditional expression of lac operon genes only when lactose is available correctly explains the resource-conserving advantage of gene regulation, matching the assertion.', difficulty: 'medium' },
  { id: 'mbi-136', type: 'count', question: 'Consider the following statements about the lac operon:\n1. The lac operon consists of three structural genes: z, y and a.\n2. The repressor protein is encoded by the "i" gene.\n3. In the presence of lactose, the repressor binds tightly to the operator, blocking transcription.\n4. Beta-galactosidase hydrolyses lactose into glucose and galactose.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — in the presence of lactose, the repressor is inactivated and detaches from the operator, permitting transcription.', difficulty: 'medium' },
  { id: 'mbi-137', type: 'count', question: 'Consider the following genes of the lac operon and their products:\n1. z gene — beta-galactosidase\n2. y gene — permease\n3. a gene — transacetylase\n4. i gene — repressor protein\nHow many of the above gene-product pairs are correctly matched?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 3, explanation: 'All four pairs are correctly matched: z — beta-galactosidase, y — permease, a — transacetylase, and i — repressor protein.', difficulty: 'medium' },
  { id: 'mbi-138', type: 'statement', question: 'Statement I: The lac operon is regulated primarily at the level of transcription.\nStatement II: Once the structural genes of the lac operon are transcribed, translation always proceeds regardless of any other cellular condition.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct — the lac operon is regulated at the transcriptional level. Statement II is an overgeneralisation and incorrect, since gene expression can also be influenced by additional regulatory factors beyond simple transcription-translation coupling.', difficulty: 'medium' },
  { id: 'mbi-139', type: 'matching', question: 'Match Column I (lac operon component) with Column II (function):\nColumn I: A. i gene  B. z gene  C. y gene  D. a gene\nColumn II: i. Permease  ii. Transacetylase  iii. Repressor protein  iv. Beta-galactosidase', options: ['A-iii, B-iv, C-i, D-ii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-ii, D-i', 'A-iii, B-i, C-iv, D-ii'], correctIndex: 0, explanation: 'i gene — repressor protein; z gene — beta-galactosidase; y gene — permease; a gene — transacetylase.', difficulty: 'medium' },

  // ============ HUMAN GENOME PROJECT ============
  { id: 'mbi-140', type: 'mcq', question: 'The Human Genome Project (HGP), a mega collaborative project completed in 2003, aimed to:', options: ['Determine the complete nucleotide sequence of human DNA and identify all human genes', 'Only sequence a single human chromosome', 'Only study genetic disorders, without sequencing DNA', 'Determine the amino acid sequence of all human proteins directly'], correctIndex: 0, explanation: 'The Human Genome Project aimed to determine the complete sequence of the human genome and identify all genes present within it.', difficulty: 'medium' },
  { id: 'mbi-141', type: 'mcq', question: 'The estimated size of the human genome, in terms of total base pairs, is approximately:', options: ['3 million base pairs', '3 billion base pairs', '3 trillion base pairs', '30,000 base pairs'], correctIndex: 1, explanation: 'The human genome is estimated to contain approximately 3 billion (3 x 10^9) base pairs.', difficulty: 'medium' },
  { id: 'mbi-142', type: 'mcq', question: 'According to the findings of the Human Genome Project, the human genome contains approximately how many protein-coding genes, a number lower than initially expected?', options: ['About 300', 'About 3,000', 'About 30,000', 'About 3 million'], correctIndex: 2, explanation: 'The Human Genome Project revealed that humans have approximately 30,000 protein-coding genes, far fewer than initially anticipated based on the complexity of the human body.', difficulty: 'medium' },
  { id: 'mbi-143', type: 'mcq', question: 'One of the goals of the Human Genome Project, as a "mega project", was to store all this generated genetic information in:', options: ['Physical notebooks alone, without digital storage', 'Computer-based databases', 'Only handwritten laboratory records', 'No storage was maintained; data was discarded after analysis'], correctIndex: 1, explanation: 'The vast amount of sequence information generated by the HGP required storage in computer-based databases for accessibility and analysis, giving rise to the field of bioinformatics.', difficulty: 'medium' },
  { id: 'mbi-144', type: 'mcq', question: 'Two major approaches used in sequencing methodologies of the Human Genome Project included the identification of genes (through cDNA sequencing) and:', options: ['Only structural analysis of proteins, without any DNA sequencing', 'Sequencing the entire genome (which contains all coding and non-coding sequences)', 'Only sequencing of ribosomal RNA genes', 'Only analysis of mitochondrial DNA'], correctIndex: 1, explanation: 'The project combined the identification of expressed genes (via cDNA sequencing) with sequencing of the entire genome, which includes both coding and non-coding regions.', difficulty: 'hard' },
  { id: 'mbi-145', type: 'mcq', question: 'A remarkable finding of the Human Genome Project was that the human genome shows a very high degree of similarity across individuals; specifically, humans are approximately:', options: ['50% identical to each other', '99.9% identical to each other, in terms of nucleotide sequence', '100% identical to each other, with zero variation', 'Only 10% identical to each other'], correctIndex: 1, explanation: 'The genome sequence data revealed that humans are approximately 99.9% identical to each other in nucleotide sequence, with a small percentage accounting for genetic diversity.', difficulty: 'medium' },
  { id: 'mbi-146', type: 'assertion', question: 'Assertion (A): The Human Genome Project has been described as a "mega project" in biology.\nReason (R): The project required an enormous scale of international collaboration, huge financial investment, and generated vast amounts of sequence data requiring sophisticated bioinformatic tools for analysis and storage.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The scale of collaboration, investment and data generated correctly explains why the HGP is regarded as a "mega project".', difficulty: 'medium' },
  { id: 'mbi-147', type: 'count', question: 'Consider the following statements about the Human Genome Project:\n1. It aimed to sequence the complete human genome.\n2. The human genome is estimated to contain about 30,000 protein-coding genes.\n3. Humans are approximately 99.9% identical to each other in their DNA sequence.\n4. The project required no computer-based storage, since the genome is relatively small.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — the vast size of the genome (3 billion base pairs) required extensive computer-based storage and analysis (bioinformatics).', difficulty: 'medium' },

  // ============ DNA FINGERPRINTING ============
  { id: 'mbi-148', type: 'mcq', question: 'The technique used to identify differences in specific regions of DNA sequence between individuals, widely used in forensic science and paternity testing, is called:', options: ['DNA fingerprinting', 'DNA replication', 'DNA cloning', 'DNA capping'], correctIndex: 0, explanation: 'DNA fingerprinting compares specific, highly variable regions of DNA between individuals, allowing identification of individuals or determination of biological relationships.', difficulty: 'easy' },
  { id: 'mbi-149', type: 'mcq', question: 'DNA fingerprinting techniques often exploit sequences known as VNTRs (variable number of tandem repeats), which are:', options: ['Repetitive DNA sequences that vary in copy number among individuals', 'Sequences found only in RNA, never in DNA', 'Genes that always code for the same protein in every individual', 'Sequences unique to only one specific species'], correctIndex: 0, explanation: 'VNTRs are repetitive DNA sequences whose number of tandem repeats varies significantly between individuals, forming the basis for DNA fingerprinting techniques.', difficulty: 'medium' },
  { id: 'mbi-150', type: 'mcq', question: 'The technique of DNA fingerprinting was originally developed by:', options: ['Alec Jeffreys', 'James Watson', 'Frederick Griffith', 'Francis Crick'], correctIndex: 0, explanation: 'Alec Jeffreys developed the technique of DNA fingerprinting, initially using satellite DNA (repetitive DNA sequences).', difficulty: 'medium' },
  { id: 'mbi-151', type: 'assertion', question: 'Assertion (A): DNA fingerprinting is a highly reliable method for individual identification.\nReason (R): The number of repeats in VNTR regions varies greatly between unrelated individuals, making the overall pattern of repeats highly specific to each individual (except identical twins).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The high degree of individual-specific variability in VNTR repeat number correctly explains the reliability of DNA fingerprinting for identification purposes.', difficulty: 'medium' },
  { id: 'mbi-152', type: 'count', question: 'Consider the following statements about DNA fingerprinting:\n1. It relies on repetitive DNA sequences that vary between individuals.\n2. It was originally developed by Alec Jeffreys.\n3. It is used in forensic investigations and paternity testing.\n4. It measures the total length of a person\'s entire genome, rather than specific repeat regions.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — DNA fingerprinting specifically analyses variable repeat regions (VNTRs), not the total genome length.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'mbi-153', type: 'mcq', question: 'Which of the following correctly represents the overall flow of genetic information, commonly summarised as the "central dogma of molecular biology"?', options: ['DNA → RNA → Protein', 'Protein → RNA → DNA', 'RNA → Protein → DNA', 'DNA → Protein → RNA'], correctIndex: 0, explanation: 'The central dogma of molecular biology states that genetic information flows from DNA to RNA (transcription) and then from RNA to protein (translation).', difficulty: 'easy' },
  { id: 'mbi-154', type: 'mcq', question: 'Which process is unique to certain viruses (retroviruses), reversing the typical direction of information flow described by the central dogma?', options: ['Transcription', 'Translation', 'Reverse transcription (RNA to DNA)', 'Replication'], correctIndex: 2, explanation: 'Retroviruses use reverse transcriptase to synthesise DNA from an RNA template, an exception to the standard direction of the central dogma.', difficulty: 'medium' },
  { id: 'mbi-155', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched?', options: ['Replication — DNA polymerase', 'Transcription — RNA polymerase', 'Translation — Ribosome', 'DNA packaging — Reverse transcriptase'], correctIndex: 3, explanation: 'Reverse transcriptase is involved in synthesising DNA from RNA (as in retroviruses), not in DNA packaging, which primarily involves histone proteins.', difficulty: 'medium' },
  { id: 'mbi-156', type: 'assertion', question: 'Assertion (A): The molecular basis of inheritance provides mechanistic explanations for classical Mendelian principles of heredity.\nReason (R): Processes such as DNA replication (accurate copying), the genetic code (specifying amino acid sequences), and gene regulation collectively explain how hereditary information is faithfully transmitted and expressed across generations.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The molecular mechanisms of replication, transcription, translation and regulation correctly explain how they collectively underpin the classical patterns of inheritance described by Mendel.', difficulty: 'medium' },
  { id: 'mbi-157', type: 'count', question: 'Consider the following statements summarising the chapter:\n1. DNA replication is semiconservative, as demonstrated by the Meselson-Stahl experiment.\n2. Transcription copies the entire genome into RNA at once, without selectivity.\n3. The genetic code is triplet, degenerate, and largely universal.\n4. The lac operon illustrates transcriptional regulation of gene expression in prokaryotes.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — transcription selectively copies specific genes/segments, not the entire genome at once.', difficulty: 'medium' },
  { id: 'mbi-158', type: 'statement', question: 'Statement I: DNA replication, transcription and translation are all template-directed processes.\nStatement II: In each of these processes, the newly synthesised molecule is chemically identical in composition to the template molecule used.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — in transcription and translation, the newly synthesised molecule (RNA or protein) is chemically different in composition from the DNA template.', difficulty: 'medium' },
  { id: 'mbi-159', type: 'mcq', question: 'Which of the following best describes why the study of the "molecular basis of inheritance" is considered foundational to modern biology?', options: ['It has no practical application beyond academic interest', 'It explains the physical and chemical basis of heredity, underlying advances in medicine, agriculture and biotechnology', 'It is relevant only to bacterial genetics, with no application to eukaryotes', 'It replaces the need to understand classical Mendelian genetics entirely'], correctIndex: 1, explanation: 'Understanding DNA structure, replication, transcription, translation and gene regulation has enabled major advances across medicine, agriculture and biotechnology, making this field foundational to modern biology.', difficulty: 'medium' },
  { id: 'mbi-160', type: 'assertion', question: 'Assertion (A): The discovery that DNA, not protein, is the genetic material was a major turning point in the history of biology.\nReason (R): Prior to definitive experiments like those of Avery, MacLeod, McCarty, and Hershey and Chase, many scientists believed proteins, due to their greater structural diversity, were more likely candidates for genetic material.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The prior belief in proteins as the likely genetic material, later overturned by definitive experiments, correctly explains why the discovery of DNA\'s role was such a pivotal moment in biology.', difficulty: 'medium' },
];
